um) {\\n    long long current_sum = 0;\\n    int count = 1;\\n    for (long long num : nums) {\\n        if (current_sum + num > max_sum) {\\n            count++;\\n            current_sum = num;\\n            if (count > k) return false;\\n        } else {\\n            current_sum += num;\\n        }\\n    }\\n    return true;\\n}\\nint main() {\\n    ios::sync_with_stdio(false);\\n    cin.tie(nullptr);\\n    int n, k;\\n    if (!(cin >> n >> k)) return 0;\\n    vector<long long> nums(n);\\n    long long low = 0, high = 0;\\n    for (int i = 0; i < n; i++) {\\n        cin >> nums[i];\\n        low = max(low, nums[i]);\\n        high += nums[i];\\n    }\\n    long long ans = high;\\n    while (low <= high) {\\n        long long mid = low + (high - low) / 2;\\n        if (canSplit(nums, k, mid)) {\\n            ans = mid;\\n            high = mid - 1;\\n        } else {\\n            low = mid + 1;\\n        }\\n    }\\n    cout << ans << \\"\\n\\";\\n    return 0;\\n}"}	2026-07-03 07:10:28.315	2026-07-03 07:10:28.315
