 cin.tie(nullptr);\\n    \\n    // Read 9 lines of 9 space-separated characters and solve\\n    \\n    return 0;\\n}"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nchar board[9][9];\\nbool isValid(int r, int c, char val) {\\n    for (int i = 0; i < 9; i++) {\\n        if (board[r][i] == val) return false;\\n        if (board[i][c] == val) return false;\\n        if (board[3*(r/3) + i/3][3*(c/3) + i%3] == val) return false;\\n    }\\n    return true;\\n}\\nbool solve() {\\n    for (int r = 0; r < 9; r++) {\\n        for (int c = 0; c < 9; c++) {\\n            if (board[r][c] == '.') {\\n                for (char val = '1'; val <= '9'; val++) {\\n                    if (isValid(r, c, val)) {\\n                        board[r][c] = val;\\n                        if (solve()) return true;\\n                        board[r][c] = '.';\\n                    }\\n                }\\n                return false;\\n            }\\n        }\\n    }\\n    return true;\\n}\\nint main() {\\n    for (int r = 0; r < 9; r++) {\\n        for (int c = 0; c < 9; c++) {\\n            cin >> board[r][c];\\n        }\\n    }\\n    if (solve()) {\\n        for (int r = 0; r < 9; r++) {\\n            for (int c = 0; c < 9; c++) {\\n                cout << board[r][c] << (c == 8 ? \\"\\" : \\" \\");\\n            }\\n            cout << \\"\\n\\";\\n        }\\n    }\\n    return 0;\\n}"}	2026-07-03 07:10:28.446	2026-07-03 07:10:28.446
a4ec24b1-c633-412a-969d-04a61143f011	Recover Binary Search Tree	You are given the root of a binary search tree (BST), where the values of exactly two nodes of the tree were swapped by mistake. Recover the tree without changing its structure.\n\nPrint the level-order BFS traversal of the recovered BST (omitting trailing nulls).\n\n**Input Format:**\n- A single line of BFS representation of the broken BST.\n\n**Output Format:**\n- The BFS representation of the recovered BST.	HARD	{tree,binary-search-tree,dfs}	ccf6772f-27d4-4001-bd5e-763e3c380ba0	[{"input": "1 3 null null 2", "title": "Example 1", "output": "3 1 null null 2", "explanation": "Inorder: [3, 2, 1]. Swapping 3 and 1 gives sorted [1, 2, 3]."}, {"input": "3 1 4 null null 2", "title": "Example 2", "output": "2 1 4 null null 3"}]	The number of nodes in the tree is in the range [2, 1000].\n-2^31 <= Node.val <= 2^31 - 1	An inorder traversal of a BST should be sorted. Find the two nodes where the sorted order is violated, and swap their values back.	**Approach: Inorder Traversal Swaps**\nPerform inorder traversal to find elements that are smaller than their predecessor. Swap values of the first and second anomalies.\nTime Complexity: O(N)\nSpace Complexity: O(H)	[{"input": "1 3 null null 2", "output": "3 1 null null 2"}, {"input": "3 1 4 null null 2", "output": "2 1 4 null null 3"}, {"input": "2 3 1", "output": "2 1 3"}, {"input": "4 2 6 1 5 3 7", "output": "4 2 6 1 3 5 7"}, {"input": "10 15 20 5 12 17 25", "output": "15 10 20 5 12 17 25"}, {"input": "3 null 2 null 1", "output": "1 null 2 null 3"}, {"input": "1 2 3", "output": "2 1 3"}, {"input": "2 3 1", "output": "2 1 3"}, {"input": "4 1 6 2 3 5 7", "output": "4 2 6 1 3 5 7"}, {"input": "2 1 3", "output": "2 1 3"}, {"input": "0 -1 1", "output": "0 -1 1"}, {"input": "25 17 12 5 20 15 10", "output": "10 17 12 5 20 15 25"}, {"input": "-1 0 -2", "output": "-1 -2 0"}, {"input": "-4 -2 null null -3", "output": "-2 -4 null null -3"}, {"input": "null", "output": "null"}, {"input": "7 6 8", "output": "7 6 8"}, {"input": "7 8 6", "output": "7 6 8"}, {"input": "1 2 0", "output": "1 0 2"}, {"input": "1 null 2 null 3", "output": "1 null 2 null 3"}, {"input": "12 13 11", "output": "12 11 13"}, {"input": "13 11 14 null null 12", "output": "12 11 14 null null 13"}, {"input": "-1 1 null null 0", "output": "1 -1 null null 0"}, {"input": "1 null 0 null -1", "output": "-1 null 0 null 1"}, {"input": "12 17 22 7 14 19 27", "output": "17 12 22 7 14 19 27"}, {"input": "2 -1 4 0 1 3 5", "output": "2 0 4 -1 1 3 5"}, {"input": "7 5 3 2 6 1 4", "output": "1 5 3 2 6 7 4"}, {"input": "7 4 9 5 6 8 10", "output": "7 5 9 4 6 8 10"}, {"input": "4 3 5", "output": "4 3 5"}, {"input": "2 null null 3 1", "output": "2"}, {"input": "-2 -4 -1 null null -3", "output": "-3 -4 -1 null null -2"}]	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\n// Recover BST skeleton\\nint main() {}"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nstruct TreeNode {\\n    int val; TreeNode *left = nullptr, *right = nullptr;\\n    TreeNode(int x) : val(x) {}\\n};\\nTreeNode* buildTree(string line) {\\n    stringstream ss(line); string val; vector<string> v;\\n    while (ss >> val) v.push_back(val);\\n    if (v.empty() || v[0] == \\"null\\") return nullptr;\\n    TreeNode* root = new TreeNode(stoi(v[0]));\\n    queue<TreeNode*> q; q.push(root);\\n    for (int i = 1; i < v.size() && !q.empty(); ) {\\n        TreeNode* curr = q.front(); q.pop();\\n        if (v[i] != \\"null\\") q.push(curr->left = new TreeNode(stoi(v[i])));\\n        i++;\\n        if (i < v.size() && v[i] != \\"null\\") q.push(curr->right = new TreeNode(stoi(v[i])));\\n        i++;\\n    }\\n    return root;\\n}\\nvoid inorder(TreeNode* r, TreeNode*& prev, TreeNode*& first, TreeNode*& second) {\\n    if (!r) return;\\n    inorder(r->left, prev, first, second);\\n    if (prev && prev->val > r->val) {\\n        if (!first) { first = prev; second = r; }\\n        else second = r;\\n    }\\n    prev = r;\\n    inorder(r->right, prev, first, second);\\n}\\nvoid printTree(TreeNode* root) {\\n    if (!root) { cout << \\"null\\n\\"; return; }\\n    vector<string> res; queue<TreeNode*> q; q.push(root);\\n    while (!q.empty()) {\\n        TreeNode* curr = q.front(); q.pop();\\n        if (curr) {\\n            res.push_back(to_string(curr->val));\\n            q.push(curr->left); q.push(curr->right);\\n        } else res.push_back(\\"null\\");\\n    }\\n    while (!res.empty() && res.back() == \\"null\\") res.pop_back();\\n    for (int i = 0; i < res.size(); i++) cout << res[i] << (i + 1 == res.size() ? \\"\\" : \\" \\");\\n    cout << \\"\\n\\";\\n}\\nint main() {\\n    ios::sync_with_stdio(false); cin.tie(nullptr);\\n    string line; if (getline(cin, line)) {\\n        TreeNode* root = buildTree(line);\\n        TreeNode *prev = nullptr, *first = nullptr, *second = nullptr;\\n        inorder(root, prev, first, second);\\n        if (first && second) swap(first->val, second->val);\\n        printTree(root);\\n    }\\n    return 0;\\n}"}	2026-07-03 07:10:28.466	2026-07-03 07:10:28.466
