turn root;\\n}\\nint main() {\\n    ios::sync_with_stdio(false); cin.tie(nullptr);\\n    string line; if (getline(cin, line)) {\\n        TreeNode* root = buildTree(line);\\n        if (!root) return 0;\\n        queue<TreeNode*> q; q.push(root);\\n        while (!q.empty()) {\\n            int sz = q.size();\\n            for (int i = 0; i < sz; i++) {\\n                TreeNode* curr = q.front(); q.pop();\\n                cout << curr->val << (i + 1 == sz ? \\"\\" : \\" \\");\\n                if (curr->left) q.push(curr->left);\\n                if (curr->right) q.push(curr->right);\\n            }\\n            cout << \\"\\n\\";\\n        }\\n    }\\n    return 0;\\n}"}	2026-07-03 07:10:28.461	2026-07-03 07:10:28.461
ebbadf0d-7310-45df-870b-7a50c2d56a1e	Balanced Binary Tree	Given the root of a binary tree, determine if it is height-balanced.\n\nA height-balanced binary tree is defined as a binary tree in which the left and right subtrees of every node differ in height by at most 1.\n\n**Input Format:**\n- A single line containing the BFS level-order serialization of the tree (using 'null' for empty nodes).\n\n**Output Format:**\n- 'true' or 'false' (lowercase string).	EASY	{tree,binary-tree,dfs}	ccf6772f-27d4-4001-bd5e-763e3c380ba0	[{"input": "3 9 20 null null 15 7", "title": "Example 1", "output": "true", "explanation": "The height of left subtree is 1 and right subtree is 2. The difference is 1, so it is balanced."}, {"input": "1 2 2 3 3 null null 4 4", "title": "Example 2", "output": "false", "explanation": "The height of left subtree is 3 and right subtree is 1. The difference is 2, so it is unbalanced."}]	The number of nodes in the tree is in the range [0, 5000].\n-10^4 <= Node.val <= 10^4	A tree is balanced if both subtrees are balanced and their height difference is at most 1. Return -1 for unbalanced height to propagate failure.	**Approach: DFS Height Check**\nRecursively compute the height of subtrees. If any subtree is unbalanced, return -1. Otherwise, return the height of the current node.\nTime Complexity: O(N)\nSpace Complexity: O(H) where H is the height of the tree.	[{"input": "3 9 20 null null 15 7", "output": "true"}, {"input": "1 2 2 3 3 null null 4 4", "output": "false"}, {"input": "null", "output": "true"}, {"input": "1", "output": "true"}, {"input": "1 2", "output": "true"}, {"input": "1 2 3 4 null null null 5", "output": "false"}, {"input": "1 null 2 null 3", "output": "false"}, {"input": "1 2 2 3 null null 3", "output": "true"}, {"input": "1 2 3 4 5 6 null 8", "output": "true"}, {"input": "1 2 null 3 null 4", "output": "false"}, {"input": "-2 -1 0 1 2 3 null 5", "output": "true"}, {"input": "-1 null 0 null 1", "output": "false"}, {"input": "2 1", "output": "true"}, {"input": "11 12 12 13 null null 13", "output": "true"}, {"input": "6 7 7 8 null null 8", "output": "true"}, {"input": "13 19 30 null null 25 17", "output": "true"}, {"input": "11 12 13 14 null null null 15", "output": "false"}, {"input": "3 4 5 6 null null null 7", "output": "false"}, {"input": "-1 0 null 1 null 2", "output": "false"}, {"input": "11 12 13 14 15 16 null 18", "output": "true"}, {"input": "2 3 3 4 4 null null 5 5", "output": "false"}, {"input": "6", "output": "true"}, {"input": "3 4", "output": "true"}, {"input": "-4 -3", "output": "true"}, {"input": "2 3 3 4 null null 4", "output": "true"}, {"input": "6 7 7 8 8 null null 9 9", "output": "false"}, {"input": "-1", "output": "true"}, {"input": "-4 -3 -3 -2 -2 null null -1 -1", "output": "false"}, {"input": "2 8 19 null null 14 6", "output": "true"}, {"input": "4 10 21 null null 16 8", "output": "true"}]	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nstruct TreeNode {\\n    int val; TreeNode *left = nullptr, *right = nullptr;\\n    TreeNode(int x) : val(x) {}\\n};\\nTreeNode* buildTree(string line) { return nullptr; }\\nint main() {\\n    ios::sync_with_stdio(false); cin.tie(nullptr);\\n    string line; if (getline(cin, line)) {\\n        TreeNode* root = buildTree(line);\\n        // Solve and print \\"true\\" or \\"false\\"\\n    }\\n    return 0;\\n}"}	{"cpp": "#include <bits/stdc++.h>\\nusing namespace std;\\nstruct TreeNode {\\n    int val; TreeNode *left = nullptr, *right = nullptr;\\n    TreeNode(int x) : val(x) {}\\n};\\nTreeNode* buildTree(string line) {\\n    stringstream ss(line); string val; vector<string> v;\\n    while (ss >> val) v.push_back(val);\\n    if (v.empty() || v[0] == \\"null\\") return nullptr;\\n    TreeNode* root = new TreeNode(stoi(v[0]));\\n    queue<TreeNode*> q; q.push(root);\\n    for (size_t i = 1; i < v.size() && !q.empty(); ) {\\n        TreeNode* curr = q.front(); q.pop();\\n        if (v[i] != \\"null\\") q.push(curr->left = new TreeNode(stoi(v[i])));\\n        i++;\\n        if (i < v.size() && v[i] != \\"null\\") q.push(curr->right = new TreeNode(stoi(v[i])));\\n        i++;\\n    }\\n    return root;\\n}\\nint checkHeight(TreeNode* r) {\\n    if (!r) return 0;\\n    int lh = checkHeight(r->left);\\n    if (lh == -1) return -1;\\n    int rh = checkHeight(r->right);\\n    if (rh == -1) return -1;\\n    if (abs(lh - rh) > 1) return -1;\\n    return 1 + max(lh, rh);\\n}\\nint main() {\\n    ios::sync_with_stdio(false); cin.tie(nullptr);\\n    string line; if (getline(cin, line)) {\\n        TreeNode* root = buildTree(line);\\n        cout << (checkHeight(root) != -1 ? \\"true\\" : \\"false\\") << \\"\\n\\";\\n    }\\n    return 0;\\n}"}	2026-07-03 07:10:28.466	2026-07-03 07:10:28.466
